inline Img mkSnowRock(int cls, int look) {
    const snowrock::Pic& p = snowrock::PICS[cls][look];
    Img im(p.w, p.h);
    int i = 0;
    for (int r = 0; r < p.nruns; r++)
        for (int k = 0; k < p.runs[r].n; k++, i++)
            if (p.runs[r].c) im.set(i % p.w, i / p.w, p.runs[r].c);
    return im;
}
